    /// ===== ② 合成用例：真语料踩不到的 JSON 分支（重复键 / 非 RFC 常量 / 语法坏）=====
    const OF_JSON_FILES: [(&str, &str); 10] = [
        (
            r#"bad.json"#,
            r#"{"a": 
"#,
        ),
        (
            r#"ctrl.json"#,
            r#"{"a": "xy"}
"#,
        ),
        (
            r#"dup.json"#,
            r#"{"a": 1, "a": 2}
"#,
        ),
        (
            r#"dup_nested.json"#,
            r#"{"o": {"k": 1, "k": 2}, "arr": [{"z": 1, "z": 2}]}
"#,
        ),
        (r#"empty.json"#, r#""#),
        (
            r#"extra.json"#,
            r#"{} {}
"#,
        ),
        (
            r#"nan.json"#,
            r#"{"v": NaN, "w": Infinity, "x": -Infinity}
"#,
        ),
        (
            r#"ok.json"#,
            r#"{"a": [1, 2.5, "s", true, null], "b": {"c": "d"}}
"#,
        ),
        (
            r#"scalar.json"#,
            r#"42
"#,
        ),
        (
            r#"unicode.json"#,
            r#"{"\u4e2d": "\ud83d\ude00"}
"#,
        ),
    ];

    #[test]
    fn output_forms_json_branches_match_truth_source() {
        let root = crate::testutil::fixture("output-forms-json-src");
        for (rel, body) in OF_JSON_FILES {
            std::fs::write(root.join(rel), body).unwrap();
        }
        let cases: &[(&str, &[&str])] = &[
            (
                r#"bad.json"#,
                &[r#"JSON 不可解析：JSON 文本 不是合法 JSON：Expecting value: line 2 column 1 (char 7)（修复指引：核对该件是否被写坏 / 含注释 / 截断）"#],
            ),
            (
                r#"ctrl.json"#,
                &[r#"JSON 不可解析：JSON 文本 不是合法 JSON：Invalid control character at: line 1 column 9 (char 8)（修复指引：核对该件是否被写坏 / 含注释 / 截断）"#],
            ),
            (r#"dup.json"#, &[r#"JSON 重复键：a"#]),
            (
                r#"dup_nested.json"#,
                &[r#"JSON 重复键：k"#, r#"JSON 重复键：z"#],
            ),
            (
                r#"empty.json"#,
                &[r#"JSON 不可解析：JSON 文本 不是合法 JSON：Expecting value: line 1 column 1 (char 0)（修复指引：核对该件是否被写坏 / 含注释 / 截断）"#],
            ),
            (
                r#"extra.json"#,
                &[r#"JSON 不可解析：JSON 文本 不是合法 JSON：Extra data: line 1 column 4 (char 3)（修复指引：核对该件是否被写坏 / 含注释 / 截断）"#],
            ),
            (r#"nan.json"#, &[]),
            (r#"ok.json"#, &[]),
            (r#"scalar.json"#, &[]),
            (r#"unicode.json"#, &[]),
        ];
        // ⚠️ **解析失败的文本不可比**（CPython `json` vs 本线 `jsonmini`）⇒ 归一到前缀后比较。
        // 归一**不削弱判据**：某例在一侧报错、另一侧不报，归一后仍会不同（那才是真结论差）。
        let norm = |v: &[String]| -> Vec<String> {
            v.iter()
                .map(|x| match x.find("JSON 不可解析：") {
                    Some(k) => format!("{}<TEXT>", &x[..k + "JSON 不可解析：".len()]),
                    None => x.clone(),
                })
                .collect()
        };
        for (rel, want) in cases {
            assert_eq!(
                norm(&check_json(&root, rel)),
                norm(&want.iter().map(|s| s.to_string()).collect::<Vec<_>>()),
                "{} 的 JSON 结论",
                rel
            );
        }
    }
